<script lang="ts">
 import RosterPicker from './common/RosterPicker.svelte';
 import { toast } from './toast';
 import { getNameCandidates,getSharedNameSplitCandidates,getSplitSuggestionsForZoomName } from './name-matching';
 export let rows:any[]=[]; export let decisions:any[]=[]; export let roster:any[]=[]; export let aliases:any[]=[]; export let nameChanges:any[]=[]; export let language='en'; export let readOnly=false;
 export let onDecision:(decision:any)=>Promise<void>=async()=>{}; export let onRevert:(id:string)=>Promise<void>=async()=>{};
 let expanded=new Set<string>(); let selected:Record<string,number|undefined>={}; let splitIds:Record<string,number[]>={}; let busy='';
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 const norm=(s:string)=>s.toLocaleLowerCase().replace(/[\s\p{P}\p{S}\u3000]/gu,'');
 const label=(r:any)=>r.zoomName||r.screenName||r.nextScreenName||'—'; const idOf=(r:any)=>r.entityId||r.sessionParticipantId||'';
 $: pending=Array.from(new Map(rows.filter(r=>r.matchStatus==='unmatched').map(r=>[idOf(r),r])).values()).filter(r=>!decisions.some(d=>d.sessionParticipantId===idOf(r)&&['match','guest','split','name_change_keep_match'].includes(d.action)));
 $: renamed=(()=>{const by=new Map<string,any[]>();for(const c of nameChanges){const id=c.sessionParticipantId;if(!id||decisions.some(d=>d.sessionParticipantId===id&&['match','guest','split','name_change_keep_match'].includes(d.action)))continue;by.set(id,[...(by.get(id)||[]),c]);}return [...by].map(([id,cs])=>{const ordered=cs.slice().sort((a,b)=>Date.parse(a.timestamp||'')-Date.parse(b.timestamp||''));return {...ordered[ordered.length-1],previousScreenName:ordered[0].previousScreenName||ordered[0].previous_screen_name,nextScreenName:ordered[ordered.length-1].nextScreenName||ordered[ordered.length-1].next_screen_name,entityId:id,sessionParticipantId:id};});})();
 function suggestions(r:any){const shared=getSharedNameSplitCandidates(label(r),roster);const historical=getSplitSuggestionsForZoomName(label(r),decisions,roster);return shared.length>=2?shared:historical.length>=2?historical:[];}
 function candidates(r:any){return getNameCandidates(label(r),roster,aliases);}
 function currentMatch(r:any){const prior=aliases.find(a=>norm(a.zoomName||a.alias||'')===norm(r.previousScreenName||''));return r.personId?`matched · ${r.canonicalName||roster.find(p=>Number(p.personId)===Number(r.personId))?.canonicalName||r.personId}`:prior?`matched · ${roster.find(p=>Number(p.personId)===Number(prior.personId))?.canonicalName||prior.personId}`:'unmatched';}
 function make(r:any,action:string,personId?:number,ids?:number[]){const p=roster.find(x=>Number(x.personId)===Number(personId));const people=(ids||[]).map(pid=>roster.find(x=>Number(x.personId)===Number(pid))).filter(Boolean);return {id:`decision-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,sessionParticipantId:idOf(r),zoomName:label(r),zoomNameAtDecision:label(r),action,...(p?{personId:p.personId,canonicalName:p.canonicalName}:{}),...(people.length?{splitPersonIds:people.map(x=>x.personId),splitCanonicalNames:people.map(x=>x.canonicalName)}:{}),createdAt:new Date().toISOString()};}
 async function act(r:any,action:string,personId?:number,ids?:number[],success?:string){const id=idOf(r);busy=id;try{await onDecision(make(r,action,personId,ids));expanded.delete(id);expanded=new Set(expanded);toast.success(success||t(`已处理 ${label(r)}。`,`Processed ${label(r)}.`));}catch(e:any){toast.error(`${t('处理失败：','Action failed: ')}${e?.message||String(e)}`);}finally{busy='';}}
 function toggle(r:any){const id=idOf(r);if(!expanded.has(id)){const sug=suggestions(r);splitIds[id]=sug.length?sug.map(p=>Number(p.personId)):r.previousScreenName?[aliases.find(a=>norm(a.zoomName||a.alias||'')===norm(r.previousScreenName))?.personId||0,0]:[];}expanded.has(id)?expanded.delete(id):expanded.add(id);expanded=new Set(expanded);splitIds={...splitIds};}
 function addSplit(r:any){const id=idOf(r);splitIds[id]=[...(splitIds[id]||[]),0];splitIds={...splitIds};}
 function dropSplit(r:any,i:number){const id=idOf(r);splitIds[id]=(splitIds[id]||[]).filter((_,n)=>n!==i);splitIds={...splitIds};}
 async function revert(d:any){try{await onRevert(d.id);toast.success(t(`已清除 ${d.zoomName} 的判定。`,`Cleared decision for ${d.zoomName}.`));}catch(e:any){toast.error(`${t('处理失败：','Action failed: ')}${e?.message||String(e)}`);}}
</script>
<section class="panel name-matching" data-testid="name-matching-panel">
 <div class="panel-title"><div><h2>{t('名称匹配','Name Matching')}</h2><p>{t('未匹配、名称变更与已处理决定','Unmatched names, name changes, and resolved decisions')}</p></div><span class="warning-count">{pending.length+renamed.length} {t('待处理','pending')}</span></div>
 <h3>{t('待处理','Pending')}</h3>
 {#each pending as r (idOf(r))}{@const id=idOf(r)}{@const c=candidates(r)}{@const sug=suggestions(r)}
 <article class="match-card"><div class="match-heading"><b title={label(r)}>{label(r)}</b><span>{c.length?c.map(p=>p.canonicalName).join(', '):t('未匹配','Unmatched')}</span></div>
  <small>{t('候选:','Candidates:')} {sug.length?sug.map(p=>p.canonicalName).join(' / '):c.map(p=>p.canonicalName).join(' / ')||t('未匹配','Unmatched')}</small>
  <div class="match-actions">{#if sug.length>=2}<button disabled={!!busy||readOnly} onclick={()=>act(r,'split',undefined,sug.map(p=>p.personId),t(`已将 ${label(r)} 标记为共用拆分。`,`Split shared account for ${label(r)}.`))}>{t('拆分共用','Split Shared')} ({sug.length})</button><button class="more" disabled={readOnly} aria-expanded={expanded.has(id)} onclick={()=>toggle(r)}>{t('更多 ▾','More ▾')}</button>{:else if c.length}{#each c as p}<button disabled={!!busy||readOnly} onclick={()=>act(r,'match',p.personId,undefined,t(`已将 ${label(r)} 关联到 ${p.canonicalName}。`,`Linked ${label(r)} to ${p.canonicalName}.`))}>{t('关联','Match')} {p.canonicalName}</button>{/each}<button class="more" disabled={readOnly} onclick={()=>toggle(r)}>{t('更多 ▾','More ▾')}</button>{:else}<button disabled={!!busy||readOnly} onclick={()=>act(r,'guest',undefined,undefined,t(`已将 ${label(r)} 标记为来宾。`,`Marked ${label(r)} as guest.`))}>{t('标记来宾','Mark Guest')}</button><button class="more" disabled={readOnly} onclick={()=>toggle(r)}>{t('更多 ▾','More ▾')}</button>{/if}</div>
  {#if expanded.has(id)}<div class="manual"><label>{t('手动关联','Manual Match')}<RosterPicker {roster} value={selected[id]} {language} disabled={!!busy||readOnly} placeholder={t('搜索花名册','Search roster')} onSelect={(personId)=>selected={...selected,[id]:personId}}/></label><button disabled={!selected[id]||!!busy||readOnly} onclick={()=>act(r,'match',selected[id],undefined,t(`已将 ${label(r)} 保存为人工匹配。`,`Saved manual match for ${label(r)}.`))}>{t('确认关联','Confirm Match')}</button>
  <fieldset><legend>{t('共用账号拆分','Shared Account Split')}</legend>{#each splitIds[id]||[] as pid,i}<div class="split-row"><RosterPicker {roster} value={pid||undefined} {language} disabled={!!busy||readOnly} placeholder={t(`拆分人员 ${i+1}`,`Split person ${i+1}`)} onSelect={(personId)=>{splitIds[id][i]=personId;splitIds={...splitIds};}}/><button disabled={readOnly} aria-label={t('移除此人','Remove person')} onclick={()=>dropSplit(r,i)}>×</button></div>{/each}<button disabled={readOnly} onclick={()=>addSplit(r)}>{t('添加人员','Add person')}</button><button disabled={new Set((splitIds[id]||[]).filter(Boolean)).size<2||!!busy||readOnly} onclick={()=>act(r,'split',undefined,splitIds[id],t(`已将 ${label(r)} 保存为拆分。`,`Saved split for ${label(r)}.`))}>{t('确认拆分','Confirm Split')}</button></fieldset></div>{/if}
 </article>
 {:else}<p class="muted">{t('当前没有待处理的名字对照项。','There are no pending reconciliation items right now.')}</p>{/each}
 <h3>{t('名称变更','Name Changes')}</h3>
 {#each renamed as r (idOf(r))}{@const id=idOf(r)}<article class="match-card"><b title={`${r.previousScreenName} → ${r.nextScreenName}`}>{r.previousScreenName} → {r.nextScreenName}</b><small>{t('当前匹配:','Current match:')} {currentMatch(r)}</small><div class="match-actions">{#if r.personId||aliases.some(a=>norm(a.zoomName||a.alias||'')===norm(r.previousScreenName||''))}<button disabled={!!busy||readOnly} onclick={()=>act(r,'name_change_keep_match',undefined,undefined,t(`已保持 ${r.nextScreenName} 的匹配。`,`Kept match for ${r.nextScreenName}.`))}>{t('保持匹配','Keep Match')}</button>{/if}<button class="more" disabled={readOnly} onclick={()=>toggle(r)}>{t('更多 ▾','More ▾')}</button></div>{#if expanded.has(id)}<div class="manual"><label>{t('手动关联','Manual Match')}<RosterPicker {roster} value={selected[id]} {language} disabled={!!busy||readOnly} onSelect={(personId)=>selected={...selected,[id]:personId}}/></label><button disabled={!selected[id]||!!busy||readOnly} onclick={()=>act(r,'match',selected[id],undefined,t(`已将 ${label(r)} 保存为人工匹配。`,`Saved manual match for ${label(r)}.`))}>{t('确认关联','Confirm Match')}</button><fieldset><legend>{t('共用账号拆分','Shared Account Split')}</legend>{#each splitIds[id]||[] as pid,i}<div class="split-row"><RosterPicker {roster} value={pid||undefined} {language} disabled={!!busy||readOnly} onSelect={(v)=>{splitIds[id][i]=v;splitIds={...splitIds};}}/><button disabled={readOnly} onclick={()=>dropSplit(r,i)}>×</button></div>{/each}<button disabled={readOnly} onclick={()=>addSplit(r)}>{t('添加人员','Add person')}</button><button disabled={new Set((splitIds[id]||[]).filter(Boolean)).size<2||!!busy||readOnly} onclick={()=>act(r,'split',undefined,splitIds[id],t(`已将 ${label(r)} 保存为拆分。`,`Saved split for ${label(r)}.`))}>{t('确认拆分','Confirm Split')}</button></fieldset></div>{/if}</article>{:else}<p class="muted">{t('当前没有需要处理的名称变更。','There are no name changes to review.')}</p>{/each}
 <h3>{t('已处理','Resolved')}</h3>
 {#each decisions as d (d.id)}<article class="resolved-row"><span>{d.zoomName}</span><span class="decision-badge">{d.action==='match'?t('已关联','Matched'):d.action==='guest'?t('来宾','Guest'):d.action==='split'?t('共用账号拆分','Shared account split'):d.action==='name_change_keep_match'?t('名称变更保持匹配','Name change keep match'):t('未知','Unknown')}</span>{#if d.canonicalName}<small>{d.canonicalName}</small>{/if}{#if d.action==='match'}<small class="auto">{t('自动匹配','Auto')}</small>{/if}{#if !readOnly}<button class="danger" disabled={!!busy} onclick={()=>revert(d)}>{t('撤销','Revert')}</button>{/if}</article>{:else}<p class="muted">{t('当前还没有已处理的记录。','There are no resolved records yet.')}</p>{/each}
</section>
<style>.name-matching{margin:16px 0}.panel-title,.match-heading,.match-actions,.resolved-row,.split-row{display:flex;align-items:center;gap:10px}.panel-title{justify-content:space-between}.panel-title h2{margin:0}.panel-title p,.muted{color:var(--muted,#78818f)}h3{font-size:13px;margin:20px 0 8px}.warning-count{color:#a56a00;background:#fff4d6;border-radius:20px;padding:5px 9px}.match-card,.resolved-row{border:1px solid #e5e8ef;border-radius:10px;padding:12px;margin:8px 0}.match-heading span{margin-left:auto;color:var(--muted,#78818f)}.match-actions{flex-wrap:wrap;margin-top:9px}.match-actions button,.manual button,.match-card button,.resolved-row button{font:inherit;cursor:pointer}.manual{padding:12px;background:#f8f9fb;border-radius:8px;margin-top:10px;display:grid;gap:9px}.manual label{display:grid;gap:5px}.manual fieldset{border:1px solid #d8dce5;border-radius:8px;display:grid;gap:8px}.resolved-row .decision-badge{padding:3px 8px;background:#edf3ff;border-radius:12px}.resolved-row button{margin-left:auto}.auto{color:#687080}</style>
